ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
((payload.label) match {
	case str if str == p('salesforce.document.fsrLabel') -> {
		"documentType": p('idp.documentType.fsr'),
		"actionName": p('idp.actionName.fsr'),
		"actionId": p('secure::idp.actionId.fsr'),
		"version": p('idp.version.fsr')
	}
    case str if str == p('salesforce.document.dnLabel') -> {
		"documentType": p('idp.documentType.dn'),
		"actionName": p('idp.actionName.dn'),
		"actionId": p('secure::idp.actionId.dn'),
		"version": p('idp.version.dn')
	}
    case str if str == p('salesforce.document.firLabel') -> {
		"documentType": p('idp.documentType.fir'),
		"actionName": p('idp.actionName.fir'),
		"actionId": p('secure::idp.actionId.fir'),
		"version": p('idp.version.fir')
	}
    case str if str == p('salesforce.document.invoiceLabel') -> {
		"documentType": p('idp.documentType.invoice'),
		"actionName": p('idp.actionName.invoice'),
		"actionId": p('secure::idp.actionId.invoice'),
		"version": p('idp.version.invoice')
	}
    case str if str == p('salesforce.document.analysisReportLabel') -> {
		"documentType": p('idp.documentType.analysisReport'),
		"actionName": p('idp.actionName.analysisReport'),
		"actionId": p('secure::idp.actionId.analysisReport'),
		"version": p('idp.version.analysisReport')
	}
    case str if str == p('salesforce.document.vendorReportLabel') -> {
		"documentType": p('idp.documentType.vendorReport'),
		"actionName": p('idp.actionName.vendorReport'),
		"actionId": p('secure::idp.actionId.vendorReport'),
		"version": p('idp.version.vendorReport')
	}
    case str if str == p('salesforce.document.ecmImageLabel') -> {
		"documentType": p('idp.documentType.ecmImage'),
		"actionName": p('idp.actionName.ecmImage'),
		"actionId": p('secure::idp.actionId.ecmImage'),
		"version": p('idp.version.ecmImage')
	}
	else -> {
	}
})

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
((payload.fields pluck ((value, key, index) -> {
	((key) : value.value) if(!isEmpty(value.value)),
	((key ++ "ConfidenceScore") : value.confidenceScore) if(!isEmpty(value.value))
}) reduce ((item, accumulator) -> item ++ accumulator))) ++ ((payload.tables mapObject ((value, key, index) -> {
	(key) : (value map ((item, index) -> item pluck ((v, k, i) -> {
		((k) : v.value) if(!isEmpty(v.value)),
		((k ++ "ConfidenceScore") : v.confidenceScore) if(!isEmpty(v.value))
	}) reduce ((item, accumulator) -> accumulator ++ item)))
})))

ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
((payload.fields pluck ((value, key, index) -> {
	((key) : value.value) if(!isEmpty(value.value)),
	(("confidenceScore") : value.confidenceScore) if(!isEmpty(value.value))
})) ++ 
(flatten(flatten(payload.tables pluck ((value, key, index) -> value)) map ((item, index) -> item pluck ((v, k, i) -> {
	((k) : v.value) if(!isEmpty(v.value)),
	(("confidenceScore") : v.confidenceScore) if(!isEmpty(v.value))
}))))) filter ((item, index) -> !isEmpty(item))

